# IronPython 2.7 -- generated by scripts/phase0mr/hfss_tsv_loop.py
import ScriptEnv, traceback, os
OUTDIR = r"/home/beams0/MGHARIB/Mohamed_stuff/HVR_OPT/results/phase0mr/hfss_run_150817"
try:
    ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
    oDesktop.RestoreWindow()
    proj = oDesktop.NewProject()
    proj.InsertDesign("HFSS", "tsvloop", "DrivenTerminal", "")
    des = proj.SetActiveDesign("tsvloop")
    ed = des.SetActiveEditor("3D Modeler")
    # the geometry is tens of micrometres; leaving the default mm units triggers the
    # "model extents smaller than one unit" warning and a poorly scaled mesh
    ed.SetModelUnits(["NAME:Units Parameter", "Units:=", "um", "Rescale:=", False])

    rv = 15          # um, copper radius
    tox = 0.5
    h  = 300
    p  = 60
    box = p * 3.0

    def cyl(name, x, y, r, z0, z1, mat):
        ed.CreateCylinder(
            ["NAME:CylinderParameters", "XCenter:=", "%gum" % x, "YCenter:=", "%gum" % y,
             "ZCenter:=", "%gum" % z0, "Radius:=", "%gum" % r,
             "Height:=", "%gum" % (z1 - z0), "WhichAxis:=", "Z", "NumSides:=", "0"],
            ["NAME:Attributes", "Name:=", name, "Flags:=", "",
             "MaterialValue:=", '"%s"' % mat, "SolveInside:=", True])

    def brick(name, x0, y0, z0, dx, dy, dz, mat, solve_inside=True):
        ed.CreateBox(
            ["NAME:BoxParameters", "XPosition:=", "%gum" % x0, "YPosition:=", "%gum" % y0,
             "ZPosition:=", "%gum" % z0, "XSize:=", "%gum" % dx,
             "YSize:=", "%gum" % dy, "ZSize:=", "%gum" % dz],
            ["NAME:Attributes", "Name:=", name, "Flags:=", "",
             "MaterialValue:=", '"%s"' % mat, "SolveInside:=", solve_inside])

    # silicon block, two lined copper vias, a copper strap shorting them at the top
    brick("sub", -box/2, -box/2, 0, box, box, h, "silicon")
    for tag, xc in (("sig", -p/2.0), ("gnd", p/2.0)):
        cyl("ox_" + tag, xc, 0.0, rv + tox, 0.0, h, "silicon_dioxide")
        cyl("cu_" + tag, xc, 0.0, rv, 0.0, h, "copper")
    brick("strap", -p/2.0 - rv, -rv, h, p + 2*rv, 2*rv, 8.0, "copper")
    # subtract the vias from the substrate so materials do not overlap
    ed.Subtract(["NAME:Selections", "Blank Parts:=", "sub",
                 "Tool Parts:=", "ox_sig,ox_gnd"],
                ["NAME:SubtractParameters", "KeepOriginals:=", True])
    ed.Subtract(["NAME:Selections", "Blank Parts:=", "ox_sig,ox_gnd",
                 "Tool Parts:=", "cu_sig,cu_gnd"],
                ["NAME:SubtractParameters", "KeepOriginals:=", True])

    # lumped port on a rectangle spanning the two via bottoms at z = 0
    ed.CreateRectangle(
        ["NAME:RectangleParameters", "IsCovered:=", True,
         "XStart:=", "%gum" % (-p/2.0), "YStart:=", "%gum" % (-rv),
         "ZStart:=", "0um", "Width:=", "%gum" % p, "Height:=", "%gum" % (2*rv),
         "WhichAxis:=", "Z"],
        ["NAME:Attributes", "Name:=", "port1", "Flags:=", "",
         "MaterialValue:=", '"vacuum"', "SolveInside:=", True])
    mod = des.GetModule("BoundarySetup")
    mod.AutoIdentifyPorts(
        ["NAME:Faces", int(ed.GetFaceIDs("port1")[0])], False,
        ["NAME:ReferenceConductors", "cu_gnd"], "P1", True)

    # radiation-free: the outer box is the silicon itself, so assign a finite-conductivity
    # boundary on its outer faces rather than radiating
    mod.AssignPerfectE(["NAME:PerfE1", "Objects:=", ["sub"], "InfGroundPlane:=", False])

    setup = des.GetModule("AnalysisSetup")
    setup.InsertSetup("HfssDriven", [
        "NAME:Setup1", "SolveType:=", "Single", "Frequency:=", "100MHz",
        "MaxDeltaS:=", 0.03, "MaximumPasses:=", 8, "MinimumPasses:=", 2,
        "MinimumConvergedPasses:=", 1, "PercentRefinement:=", 30,
        "BasisOrder:=", 1, "UseIterativeSolver:=", False])
    setup.InsertFrequencySweep("Setup1", [
        "NAME:Sweep", "IsEnabled:=", True, "Type:=", "Discrete",
        "RangeType:=", "LogScale", "RangeStart:=", "1MHz", "RangeEnd:=", "100MHz",
        "RangeSamples:=", 3,
        "SaveFields:=", False, "SaveRadFields:=", False, "ExtrapToDC:=", False])
    des.Analyze("Setup1")

    rep = des.GetModule("ReportSetup")
    rep.CreateReport("Zreal", "Terminal Solution Data", "Rectangular Plot",
                     "Setup1 : Sweep", ["Domain:=", "Sweep"],
                     ["Freq:=", ["All"]],
                     ["X Component:=", "Freq",
                      "Y Component:=", ["re(Zt(P1_T1,P1_T1))", "im(Zt(P1_T1,P1_T1))"]], [])
    rep.ExportToFile("Zreal", os.path.join(OUTDIR, "hfss_z.csv"), False)
    f = open(os.path.join(OUTDIR, "hfss_ok.txt"), "w")
    f.write("AEDT %s OK\n" % oDesktop.GetVersion())
    f.close()
    oDesktop.QuitApplication()
except Exception:
    f = open(os.path.join(OUTDIR, "hfss_err.txt"), "w")
    f.write(traceback.format_exc())
    f.close()
    try:
        oDesktop.QuitApplication()
    except Exception:
        pass
